<script setup lang="ts">
import {ArrowLeft,ArrowUpRight,Columns3,Landmark,Move3D,Search,BookOpen,Heart,Bookmark,Clock3} from 'lucide-vue-next'
import {normalizeBookSearch} from '~/utils/library/navigation'
import {latestReadingBookmark,readingPositionLabel} from '~/utils/library/reading'
import {libraryTopics,type LibraryBook} from '~/data/library/catalog'
const {data:catalog}=await useFetch('/api/library')
const libraryBooks=ref<readonly LibraryBook[]>(catalog.value?.items||[])
const catalogPage=ref(1),moreCatalog=ref(Boolean(catalog.value?.hasMore)),loadingCatalog=ref(false)
async function loadMoreCatalog(){loadingCatalog.value=true;try{const next=await $fetch('/api/library',{query:{page:catalogPage.value+1}});libraryBooks.value=[...libraryBooks.value,...next.items];catalogPage.value++;moreCatalog.value=Boolean(next.hasMore)}finally{loadingCatalog.value=false}}
const hall=ref<{visit:(index:number)=>void;reset:()=>void;focusBook:(id:string)=>void}>(),active=ref<number|null>(null),ready=ref(false)
const {library,toggleBook}=useProgress()
const {records,load}=useLibraryReading()
const resumeBookmarks=computed(()=>Object.fromEntries(Object.entries(records.value).map(([id,state])=>[id,latestReadingBookmark(state)])))
const readerStart=ref<'beginning'|'bookmark'|'resume'>('resume')
const personal=ref<'all'|'favorites'|'reading'|'bookmarks'>('all')
const query=ref(''),limit=ref(12),reader=ref<LibraryBook|null>(null),roomFrame=ref<HTMLElement>()
const filteredBooks=computed(()=>{const term=normalizeBookSearch(query.value);return libraryBooks.value.filter(book=>(personal.value==='all'||personal.value==='favorites'&&library.value.includes(book.id)||personal.value==='reading'&&Boolean(records.value[book.id]?.updatedAt)&&(library.value.includes(book.id)||Boolean(records.value[book.id]?.bookmarks.length))||personal.value==='bookmarks'&&Boolean(records.value[book.id]?.bookmarks.length))&&(active.value===null||book.shelf===active.value)&&normalizeBookSearch(`${book.title} ${book.originalTitle} ${book.author}`).includes(term))})
const availableTopics=computed(()=>libraryTopics.map(topic=>({...topic,count:libraryBooks.value.filter(book=>book.topic===topic.id).length})).filter(topic=>topic.count>0))
const visibleBooks=computed(()=>filteredBooks.value.slice(0,limit.value))
onMounted(()=>libraryBooks.value.forEach(book=>load(book.id)))
watch([query,active,personal],()=>{limit.value=12})
function visit(index:number){active.value=index;hall.value?.visit(index)}
function findBook(book:LibraryBook){active.value=book.shelf;hall.value?.focusBook(book.id);roomFrame.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}
function readBook(id:string,start:'beginning'|'bookmark'|'resume'='resume'){readerStart.value=start;reader.value=libraryBooks.value.find(book=>book.id===id&&book.file)||null}

useHead({title:'Վիրտուալ գրադարան — COGNITIO'})
</script>
<template>
 <main class="grand-library-page">
  <div class="library-path"><NuxtLink to="/"><ArrowLeft :size="14"/>Գլխավոր</NuxtLink><span>COGNITIO · ՎԻՐՏՈՒԱԼ ԳՐԱԴԱՐԱՆ</span><span class="room-number">ԱՌԱՋԻՆ ՍՐԱՀ</span></div>
  <header class="library-title"><div><p class="library-kicker">ՄԻ ՏԱՐԱԾՔ, ՀԱԶԱՐ ԱՇԽԱՐՀ</p><h1>Գիտելիքի <em>մեծ սրահը</em></h1><p class="library-subtitle">Մարմարե սյուների ու ոսկեգույն գմբեթի ներքո՝ քո հաջորդ բացահայտումը։</p></div><div class="library-seal" aria-hidden="true"><Landmark :size="32" :stroke-width="1"/><span>COGNITIO</span></div></header>
  <section ref="roomFrame" class="grand-library-frame" aria-label="Գրադարանի ինտերակտիվ 3D միջավայր"><ClientOnly><LazyLibraryGrandHall :key="libraryBooks.length" ref="hall" :books="libraryBooks" :paused="Boolean(reader)" @ready="ready=true" @read="readBook"/><template #fallback><div class="library-placeholder"><Landmark :size="42" :stroke-width="1"/><span>Բացում ենք սրահի դռները…</span></div></template></ClientOnly></section>
  <nav class="library-room-nav" aria-label="Մոտենալ գրադարանի բաժիններին"><button :disabled="!ready" :class="{active:active===null}" :aria-pressed="active===null" @click="active=null;hall?.reset()"><Columns3 :size="18"/><span>Ամբողջ սրահը</span></button><button v-for="topic in availableTopics" :key="topic.id" :disabled="!ready" :class="{active:active===topic.shelf}" :aria-pressed="active===topic.shelf" @click="visit(topic.shelf)"><small>{{topic.count}} գիրք</small><span>{{topic.short}}</span><ArrowUpRight :size="15"/></button></nav>
  <section class="library-editions" aria-label="Գրքերը և բաժինները"><nav class="personal-library-tabs" aria-label="Իմ գրադարանը"><button :aria-pressed="personal==='all'" @click="personal='all'">Բոլոր գրքերը</button><button :aria-pressed="personal==='favorites'" @click="personal='favorites';active=null"><Heart :size="15"/>Պահպանված գրքեր</button><button :aria-pressed="personal==='reading'" @click="personal='reading';active=null"><Clock3 :size="15"/>Շարունակել կարդալ</button><button :aria-pressed="personal==='bookmarks'" @click="personal='bookmarks';active=null"><Bookmark :size="15"/>Էջանշաններով</button></nav><header><div><h2>Գտիր քո գիրքը</h2><p>{{catalog?.total||libraryBooks.length}} տարբեր գիրք · Հայերեն բնագրեր</p></div><label class="catalog-search"><Search :size="17"/><input v-model="query" type="search" placeholder="Գրքի անուն կամ հեղինակ…" aria-label="Որոնել գրադարանի գրքերը"/></label></header><p class="catalog-results" role="status">{{filteredBooks.length}} գիրք{{active!==null?' · '+libraryTopics.find(topic=>topic.shelf===active)?.short:''}}</p><div class="edition-grid"><article v-for="book in visibleBooks" :key="book.id" class="edition-card"><button :disabled="!ready" @click="findBook(book)"><img :src="book.cover" :alt="book.title" loading="lazy" decoding="async"/><span><small>{{libraryTopics.find(topic=>topic.id===book.topic)?.short}}</small><strong>{{book.title}}</strong><span>{{book.author}}</span><b>Գտնել դարակում ↗</b></span></button><button type="button" class="catalog-favorite save-control" :aria-pressed="library.includes(book.id)" @click="toggleBook(book.id)"><Heart :size="14" :fill="library.includes(book.id)?'currentColor':'none'"/>{{library.includes(book.id)?'Պահպանված է':'Պահպանել'}}</button><div v-if="book.file" class="catalog-reading-actions"><button type="button" class="catalog-read" @click="readBook(book.id,'beginning')"><BookOpen :size="14"/>Կարդալ</button><button v-if="resumeBookmarks[book.id]" type="button" class="catalog-read catalog-resume" :title="'Շարունակել կարդալ · '+(resumeBookmarks[book.id]!.excerpt||readingPositionLabel(book.topic,resumeBookmarks[book.id]!))" :aria-label="'Շարունակել կարդալ · '+readingPositionLabel(book.topic,resumeBookmarks[book.id]!)" @click="readBook(book.id,'bookmark')"><Clock3 :size="14"/><span>{{readingPositionLabel(book.topic,resumeBookmarks[book.id]!)}}</span></button></div></article></div><div v-if="!filteredBooks.length" class="catalog-empty">Գիրք չի գտնվել։ Փոխիր որոնումը կամ ընտրիր «Ամբողջ սրահը»։</div><button v-if="visibleBooks.length<filteredBooks.length" class="catalog-more" @click="limit+=12">Ցույց տալ հաջորդ գրքերը</button></section>
  <LazyLibraryBookReader v-if="reader" :key="reader.id+':'+readerStart" :book="reader" :start="readerStart" @close="reader=null"/>
  <button v-if="moreCatalog" class="catalog-more" :disabled="loadingCatalog" @click="loadMoreCatalog">{{loadingCatalog?'Բեռնվում է…':'Բեռնել ևս գրքեր'}}</button>
  <footer class="library-room-note"><span><Move3D :size="15"/>Քայլիր սրահում և բացահայտիր տարածքը։</span><p>Ոգեշնչված ԱՄՆ Կոնգրեսի գրադարանի շքեղ ընթերցասրահից։ <a href="https://www.loc.gov/about/online-tours/thomas-jefferson-building/main-reading-room/" target="_blank" rel="noopener noreferrer">Տես ոգեշնչման աղբյուրը ↗</a></p></footer>
 </main>
</template>
